create table public.dream_desk_reports (report_key text primary key, chat_id text not null, report_date date, update_id bigint not null, status text not null check(status in ('sending','sent','uncertain')), body text not null, summary jsonb, message_id bigint, created_at timestamptz not null default now()); alter table public.dream_desk_reports enable row level security; revoke all on public.dream_desk_reports from anon,authenticated; grant select,insert,update on public.dream_desk_reports to service_role;